old = "    async def subscribe_stock_snapshot(\n            self,\n            symbols: list[str],\n            callback: SubscriptionCallback,\n            data_type: str = \"snapshot\",\n            **kwargs: Any,\n    ) -> bool:\n        if not getattr(self.config, \"subscription_enabled\", True):\n            raise DataProviderError(\"AmazingData process subscription is disabled by configuration\")\n        if not callable(callback):\n            raise DataProviderError(\"AmazingData process subscription callback must be callable\")\n\n        raw_type = (data_type or \"snapshot\").strip()\n        canonical_map = {\n            \"snapshot\": \"snapshot\",\n            \"realtime\": \"snapshot\",\n            \"snapshotindex\": \"snapshotindex\",\n            \"snapshotfuture\": \"snapshotfuture\",\n            \"snapshothkt\": \"snapshothkt\",\n            \"snapshotetf\": \"snapshotetf\",\n            \"snapshotkzz\": \"snapshotkzz\",\n        }\n        canonical_key = _normalize_period_token(raw_type)\n        canonical_type = canonical_map.get(canonical_key)\n        if canonical_type is None:\n            raise DataProviderError(f\"AmazingData process does not support data_type={data_type!r}\")\n\n        expected_periods = {\n            \"snapshot\": {\"snapshot\", \"realtime\", \"\"},\n            \"snapshotindex\": {\"snapshotindex\"},\n            \"snapshotfuture\": {\"snapshotfuture\"},\n            \"snapshothkt\": {\"snapshothkt\"},\n            \"snapshotetf\": {\"snapshotetf\"},\n            \"snapshotkzz\": {\"snapshotkzz\"},\n        }\n        period_hint = _normalize_period_token(kwargs.get(\"period\") or canonical_type)\n        if period_hint and period_hint not in expected_periods.get(canonical_type, {canonical_type}):\n            raise DataProviderError(\n                f\"AmazingData process period={kwargs.get('period')!r} does not match data_type={data_type!r}\"\n            )\n\n        normalized_codes = [\n            code.strip().upper()\n            for code in symbols\n            if isinstance(code, str) and code.strip()\n        ]\n        if not normalized_codes:\n            logger.debug(\n                \"AmazingData process subscribe_stock_snapshot ignored empty codes list\"\n            )\n            return False\n        unique_codes = list(dict.fromkeys(normalized_codes))\n\n        initialized = await self.initialize()\n        if not initialized or not self.is_connected():\n            raise DataProviderError(\"AmazingData process is not connected; cannot subscribe\")\n\n        callbacks_snapshot: dict[str, tuple[SubscriptionCallback, ...]] = {}\n        should_start = False\n        async with self._subscription_lock:\n            for code in unique_codes:\n                bucket = self._subscription_callbacks.get(code)\n                if bucket is None:\n                    bucket = set()\n                    self._subscription_callbacks[code] = bucket\n                bucket.add(callback)\n                callbacks_snapshot[code] = tuple(bucket)\n            task = self._subscription_task\n            should_start = task is None or task.done()\n\n        if should_start:\n            self._start_subscription_loop()\n\n        logger.info(\n            \"AmazingData process prepared snapshot subscription codes={} poll_interval={:.2f}s batch_size={}\",\n            len(unique_codes),\n            self._subscription_poll_interval,\n            self._subscription_batch_size,\n        )\n\n        asyncio.create_task(self._dispatch_subscription_payloads(unique_codes, callbacks_snapshot))\n        return True\n\n"
new = "    async def subscribe_stock_snapshot(\n            self,\n            symbols: list[str],\n            callback: SubscriptionCallback,\n            data_type: str = \"snapshot\",\n            **kwargs: Any,\n    ) -> bool:\n        if not getattr(self.config, \"subscription_enabled\", True):\n            raise DataProviderError(\"AmazingData process subscription is disabled by configuration\")\n        if not callable(callback):\n            raise DataProviderError(\"AmazingData process subscription callback must be callable\")\n\n        raw_type = (data_type or \"snapshot\").strip()\n        canonical_map = {\n            \"snapshot\": \"snapshot\",\n            \"realtime\": \"snapshot\",\n            \"snapshotindex\": \"snapshotindex\",\n            \"snapshotfuture\": \"snapshotfuture\",\n            \"snapshothkt\": \"snapshothkt\",\n            \"snapshotetf\": \"snapshotetf\",\n            \"snapshotkzz\": \"snapshotkzz\",\n        }\n        canonical_key = _normalize_period_token(raw_type)\n        canonical_type = canonical_map.get(canonical_key)\n        if canonical_type is None:\n            raise DataProviderError(f\"AmazingData process does not support data_type={data_type!r}\")\n\n        expected_periods = {\n            \"snapshot\": {\"snapshot\", \"realtime\", \"\"},\n            \"snapshotindex\": {\"snapshotindex\"},\n            \"snapshotfuture\": {\"snapshotfuture\"},\n            \"snapshothkt\": {\"snapshothkt\"},\n            \"snapshotetf\": {\"snapshotetf\"},\n            \"snapshotkzz\": {\"snapshotkzz\"},\n        }\n        period_hint = _normalize_period_token(kwargs.get(\"period\") or canonical_type)\n        if period_hint and period_hint not in expected_periods.get(canonical_type, {canonical_type}):\n            raise DataProviderError(\n                f\"AmazingData process period={kwargs.get('period')!r} does not match data_type={data_type!r}\"\n            )\n\n        normalized_codes = [\n            code.strip().upper()\n            for code in symbols\n            if isinstance(code, str) and code.strip()\n        ]\n        if not normalized_codes:\n            logger.debug(\n                \"AmazingData process subscribe_stock_snapshot ignored empty codes list\"\n            )\n            return False\n        unique_codes = list(dict.fromkeys(normalized_codes))\n\n        initialized = await self.initialize()\n        if not initialized or not self.is_connected():\n            raise DataProviderError(\"AmazingData process is not connected; cannot subscribe\")\n\n        callbacks_snapshot: dict[str, tuple[SubscriptionCallback, ...]] = {}\n        should_start = False\n        async with self._subscription_lock:\n            self._subscription_registry.add(unique_codes, callback, canonical_type)\n            for code in unique_codes:\n                bucket = self._subscription_callbacks.get(code)\n                if bucket is None:\n                    bucket = set()\n                    self._subscription_callbacks[code] = bucket\n                bucket.add(callback)\n                info = self._subscription_registry.get(code)\n                if info and info.callbacks:\n                    callbacks_snapshot[code] = tuple(info.callbacks)\n            task = self._subscription_task\n            should_start = task is None or task.done()\n\n        if should_start:\n            self._start_subscription_loop()\n\n        logger.info(\n            \"AmazingData process prepared snapshot subscription codes={} poll_interval={:.2f}s batch_size={}\",\n            len(unique_codes),\n            self._subscription_poll_interval,\n            self._subscription_batch_size,\n        )\n\n        asyncio.create_task(self._dispatch_subscription_payloads(unique_codes, callbacks_snapshot))\n        return True\n\n"
